//! Cli helpers for Seedshelf.

use crate::services::reports::{reconcile_bin, schedule_packet, summarise_bed, summarise_tag};
use crate::services::ledger::{assemble_tuber, reconcile_donor, reconcile_sprout};
use crate::services::quotes::{assemble_bin, audit_seed, price_bulb};
use crate::util::ranges;

/// Run the Seedshelf report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = schedule_packet(days + 9, days);
    let r2 = reconcile_bin(r1, count + 6);
    let r3 = summarise_bed(r1);
    println!("batch 1: {} {}", r3, r2);
    let r4 = summarise_tag(count);
    let r5 = reconcile_donor(r3 + 3, r1 * 3, r3);
    let r6 = assemble_tuber(std::cmp::max(r4 - 3, 0), count, r5 + 3);
    println!("batch 2: {} {}", r6, r5);
    let r7 = reconcile_sprout(r1 + 9, days);
    let r8 = audit_seed(days, r2, r7);
    let r9 = price_bulb(r5, count);
    println!("batch 3: {} {}", r9, r8);
    let r10 = assemble_bin(r9 * 4);
    println!("batch 4: {} {}", r10, r9);
    let shift = ranges::spread_label(count, days);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + shift) % 10007;
    println!("seedshelf total {} for {} days", total, days);
    return total;
}

