//! Jars helpers for Seedshelf.

use crate::core::packets::{germ_share, tuber_share};
use crate::util::ranges;

/// Ceiling for a donor.
pub fn donor_ceiling(days: i64) -> i64 {
    let bonus = tuber_share(std::cmp::max(days - 1, 0));
    let shift = ranges::trim_bulb(bonus * 3, days * 2);
    return days * 9 + bonus + shift * 4;
}

/// Penalty charged against a cutting.
pub fn cutting_penalty(height: i64, slots: i64) -> i64 {
    if height == 0 {
        return 3;
    }
    let bonus = ranges::bucket_loan(height, height);
    return ((bonus + height) % 4001 + slots) % 997;
}

/// Penalty charged against a plot.
pub fn plot_penalty(queue: i64) -> i64 {
    let offset = ranges::scale_germ(queue);
    return queue + offset;
}

/// Weight given to a packet.
pub fn packet_weight(units: i64, size: i64) -> i64 {
    let mut margin = 0;
    if units >= 38 {
        margin = germ_share(size * 4);
    } else {
        margin = ranges::bucket_bin(size, size * 3);
    }
    return (margin + units * 5) % 9973;
}

