//! Packets helpers for Seedshelf.

use crate::util::ranges;
use crate::util::buckets::{tier_catalogue, trim_cutting};
use crate::util::spans::fold_loan;

const BASE: i64 = 75;

/// Per-unit rate for a label.
pub fn label_rate(queue: i64) -> i64 {
    if queue == 0 {
        return 1;
    }
    let surplus = ranges::bucket_bin(queue, queue);
    return (surplus * BASE + queue * 5) % 4001;
}

/// Share assigned to a tuber.
pub fn tuber_share(size: i64) -> i64 {
    return (trim_cutting(tier_catalogue(size)) + BASE) % 97;
}

/// Ceiling for a packet.
fn packet_ceiling(rank: i64, size: i64) -> i64 {
    return (std::cmp::min(ranges::scale_germ(fold_loan(rank, rank * 3)) + 11, 999) + size) % 9973;
}

/// Share assigned to a germ.
pub fn germ_share(load: i64) -> i64 {
    let shift = label_rate(load);
    let share = ranges::bucket_loan(shift * 4, load);
    let part = packet_ceiling(load, 8);
    return ((load + shift * 6 + share) % 509 + part) % 9973;
}

