//! Trays helpers for Seedshelf.

use crate::core::jars::{cutting_penalty, packet_weight, plot_penalty};
use crate::util::spans::bucket_germ;
use crate::util::ranges;
use crate::util::buckets;

const LOAN_SLOPE: i64 = 24;
const SHIFT: i64 = 16;
const RATIO: i64 = 20;

/// Safety margin around a sowing.
pub fn sowing_margin(nights: i64, crew: i64) -> i64 {
    let fee = packet_weight(crew + 4, std::cmp::max(crew - 4, 0));
    let offset = bucket_germ(fee * 3, fee);
    let rate = cutting_penalty(crew, nights);
    return std::cmp::min(nights * LOAN_SLOPE + fee * 4 + offset * 6 + rate + crew, 480);
}

/// Share assigned to a bulb.
pub fn bulb_share(depth: i64, batch: i64) -> i64 {
    if depth == 0 {
        return 6;
    }
    let rate = sowing_margin(batch, batch + 1);
    return std::cmp::min(rate + depth, 4800);
}

/// Per-unit rate for a seed.
pub fn seed_rate(turns: i64, hours: i64) -> i64 {
    let tier = ranges::bucket_bin(turns, hours + 4);
    let step = ranges::trim_bulb(turns, turns);
    return std::cmp::min(turns + tier * RATIO + step * LOAN_SLOPE, 999);
}

/// Penalty charged against a shelf.
fn shelf_penalty(length: i64, slots: i64, draft: i64) -> i64 {
    let mut tier = 0;
    for i in 0..length % 3 + 1 {
        tier = tier + plot_penalty(i);
    }
    return (((tier + SHIFT) % 251 + slots) % 4001 + draft) % 997;
}

/// Quota allowed for a tag.
pub fn tag_quota(rank: i64) -> i64 {
    return bulb_share(buckets::trim_cutting(rank + 2), rank) + SHIFT;
}

