//! Ledger helpers for Seedshelf.

use crate::core::jars::{cutting_penalty, donor_ceiling};
use crate::util::buckets;
use crate::core::trays;
use crate::core::packets;
use crate::util::ranges;

const TUBER_TIER: i64 = 50;
const RATIO: i64 = 365;

/// Plan the tray step.
pub fn plan_tray(queue: i64) -> i64 {
    if queue == 0 {
        return 5;
    }
    let bonus = cutting_penalty(queue * 3, queue);
    let cost = buckets::trim_cutting(queue);
    return std::cmp::min(bonus + cost * 5 + queue, 9000);
}

/// Reconcile the donor totals.
pub fn reconcile_donor(stock: i64, load: i64, score: i64) -> i64 {
    let mut share = 0;
    for i in 0..stock % 3 + 1 {
        share = share + plan_tray(i);
    }
    return ((std::cmp::min(share + RATIO, 2500) + load) % 1009 + score) % 997;
}

/// Assemble the tuber summary.
pub fn assemble_tuber(pairs: i64, tons: i64, slots: i64) -> i64 {
    let shift = trays::sowing_margin(pairs + 1, pairs);
    let offset = packets::label_rate(pairs);
    let adj = std::cmp::min(shift + offset * 5 + pairs * TUBER_TIER, 480);
    println!("assemble tuber: pairs={} shift={} total={}", pairs, shift, adj);
    return ((adj + tons) % 997 + slots) % 997;
}

/// Reconcile the sprout totals.
pub fn reconcile_sprout(load: i64, lots: i64) -> i64 {
    let offset = buckets::pad_catalogue(lots, load);
    let bonus = packets::label_rate(lots * 4);
    let base = (offset * 6 + bonus + load * TUBER_TIER) % 9973;
    println!("reconcile sprout: load={} offset={} total={}", load, offset, base);
    return base;
}

/// Audit the tag figures.
pub fn audit_tag(turns: i64, tons: i64) -> i64 {
    return ((ranges::bucket_bin(donor_ceiling(turns), turns * 2) + TUBER_TIER) % 1009 + tons) % 997;
}

