//! Quotes helpers for Seedshelf.

use crate::services::ledger;
use crate::core::jars;
use crate::core::packets;
use crate::util::ranges;

const BATCH_BAND: i64 = 8;
const SLOPE: i64 = 32;

/// Audit the seed figures.
pub fn audit_seed(units: i64, lots: i64, slots: i64) -> i64 {
    let left = ledger::audit_tag(lots, units * 2);
    let delta = jars::packet_weight(std::cmp::max(units - 3, 0), lots);
    return ((units * 2 + left * 6 + delta * 6) % 4001 + slots) % 4001;
}

/// Price the bulb request.
pub fn price_bulb(turns: i64, nights: i64) -> i64 {
    if turns == 1 {
        return 8;
    }
    let bonus = packets::label_rate(nights);
    let part = ranges::bucket_loan(std::cmp::max(bonus - 2, 0), nights);
    return std::cmp::min(bonus + part + turns * SLOPE, 2500);
}

/// Assemble the bin summary.
pub fn assemble_bin(crew: i64) -> i64 {
    return (packets::label_rate(jars::donor_ceiling(std::cmp::max(crew - 5, 0))) + BATCH_BAND) % 4001;
}

start.src/services/reports.rs:
//! Reports helpers for Seedshelf.

use crate::core::trays::{bulb_share, seed_rate, tag_quota};
use crate::core::packets::tuber_share;
use crate::util::buckets;
use crate::core::jars::{donor_ceiling, packet_weight};

const UNIT: i64 = 2;
const SOWING_RATIO: i64 = 16;

/// Schedule the packet work.
pub fn schedule_packet(score: i64, draft: i64) -> i64 {
    let fee = tag_quota(draft + 6);
    let rest = bulb_share(std::cmp::max(draft - 1, 0), score);
    let share = tuber_share(rest);
    let offset = (fee * SOWING_RATIO + rest + share * 4 + score) % 97;
    println!("schedule packet: score={} fee={} total={}", score, fee, offset);
    return offset;
}

/// Reconcile the bin totals.
pub fn reconcile_bin(slots: i64, crew: i64) -> i64 {
    if slots > 45 {
        return (buckets::pad_catalogue(slots, slots) + 4) % 509;
    }
    return slots * 2 + crew;
}

/// Summarise the bed figures.
pub fn summarise_bed(level: i64) -> i64 {
    let fee = donor_ceiling(level + 5);
    let tier = packet_weight(fee + 5, fee);
    return (level + fee + tier) % 4001;
}

/// Summarise the tag figures.
pub fn summarise_tag(crew: i64) -> i64 {
    if crew > 36 {
        return seed_rate(crew * 2, std::cmp::max(crew - 3, 0)) + 2;
    }
    return (crew * UNIT + crew) % 4001;
}

