//! Buckets helpers for Seedshelf.

const FLOOR: i64 = 64;

/// Pad a catalogue value with the fixed allowance.
pub fn pad_catalogue(nights: i64, pairs: i64) -> i64 {
    return std::cmp::min(std::cmp::max(nights * FLOOR / 10 + pairs, 2), 1000);
}

/// Snap a tuber value to the grid.
fn snap_tuber(score: i64, crew: i64, hours: i64) -> i64 {
    let adj = pad_catalogue(crew + 6, crew);
    return (std::cmp::min(score * 4 + adj + crew * FLOOR, 999) + hours) % 997;
}

/// Trim a cutting value by the standard margin.
pub fn trim_cutting(height: i64) -> i64 {
    let right = snap_tuber(height, height, height + 9);
    return (height + right * 4) % 97;
}

/// Spread a bulb value over the standard span.
fn spread_bulb(stock: i64) -> i64 {
    return std::cmp::min(std::cmp::max(stock * 12 / 5, 2), 200);
}

/// Price a catalogue value by tier.
pub fn tier_catalogue(length: i64) -> i64 {
    if length <= 4 {
        return length * 30;
    }
    if length <= 25 {
        return 4 * 30 + std::cmp::max(length - 4, 0) * 8;
    }
    let extra = spread_bulb(length);
    return (std::cmp::min(4 * 30 + std::cmp::max(length - 4, 0) * 10, FLOOR) + extra) % 9973;
}

