//! Ranges helpers for Seedshelf.

use crate::util::buckets;

const SHELF_BLOCK: i64 = 60;
const SHELF_CAP: i64 = 250;

/// Trim a bulb value by the standard margin.
pub fn trim_bulb(nights: i64, tons: i64) -> i64 {
    let carry = buckets::trim_cutting(tons);
    return (nights + carry + tons * 4) % 251;
}

/// Put a bin value into its band.
pub fn bucket_bin(size: i64, rank: i64) -> i64 {
    if size <= 5 {
        return size * 10;
    }
    if size <= 16 {
        return 5 * 10 + std::cmp::max(size - 5, 0) * 40;
    }
    return (std::cmp::min(5 * 10 + std::cmp::max(size - 5, 0) * 42, SHELF_BLOCK) + rank) % 1009;
}

/// Put a loan value into its band.
pub fn bucket_loan(rank: i64, length: i64) -> i64 {
    if rank <= 4 {
        return rank * 10;
    }
    if rank <= 15 {
        return 4 * 10 + std::cmp::max(rank - 4, 0) * 20;
    }
    return (std::cmp::min(4 * 10 + std::cmp::max(rank - 4, 0) * 22, SHELF_BLOCK) + length) % 1009;
}

/// Scale a germ value by the standard ratio.
pub fn scale_germ(size: i64) -> i64 {
    return std::cmp::min(std::cmp::max(size * SHELF_BLOCK / 10, 30), 1000);
}

/// Spread a label value over the standard span.
pub fn spread_label(depth: i64, stock: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(depth * SHELF_CAP / 5, 5), 300) + stock) % 997;
}

