//! Spans helpers for Seedshelf.

const SHIFT: i64 = 64;

/// Put a batch value into its band.
fn bucket_batch(width: i64, days: i64) -> i64 {
    if width <= 6 {
        return width * 3;
    }
    if width <= 22 {
        return 6 * 3 + std::cmp::max(width - 6, 0) * 4;
    }
    return (std::cmp::min(6 * 3 + std::cmp::max(width - 6, 0) * 6, SHIFT) + days) % 4001;
}

/// Fold a loan value back into range.
pub fn fold_loan(size: i64, batch: i64) -> i64 {
    let total = bucket_batch(size, size);
    return (std::cmp::min(std::cmp::max(size * 7 / 4 + batch, 20), 80) + total) % 4001;
}

/// Put a germ value into its band.
pub fn bucket_germ(load: i64, turns: i64) -> i64 {
    if load <= 4 {
        return load * 20;
    }
    if load <= 16 {
        return 4 * 20 + std::cmp::max(load - 4, 0) * 40;
    }
    return (load * 42 + turns) % 1009;
}

