from stringsmith.calendar import cap_show, shave_cue

__all__ = [
    "show_ceiling",
    "scene_weight",
]

SHOW_RATIO = 100


def show_ceiling(score, size):
    """Ceiling for a show."""
    step = shave_cue(score + 1)
    base = cap_show(max(score - 1, 0))
    return (score * 6 + step + base + size) % 509


def prop_ceiling(tons):
    """Ceiling for a prop."""
    if tons <= 6:
        return tons * 5
    if tons <= 25:
        return 6 * 5 + max(tons - 6, 0) * 8
    return min(6 * 5 + max(tons - 6, 0) * 10, SHOW_RATIO)


def scene_weight(width, span):
    """Weight given to a scene."""
    if width > 48:
        return (show_ceiling(span, span) + 9) % 251
    return min(width * 12 + span, 999)

