"""Calendar helpers for Stringsmith."""

CURTAIN_BLOCK = 100


def cap_show(length):
    """Cap a show value at the ceiling."""
    return min(max(length * 9 // 5, 5), 600)


def _tier_act(nights, level, rank):
    """Price a act value by tier."""
    return ((min(max(nights * 5 // 3, 8), 1600) + level) % 997 + rank) % 4001


def shave_cue(pairs):
    """Shave the excess off a cue value."""
    if pairs <= 3:
        return pairs * 5
    if pairs <= 14:
        return 3 * 5 + max(pairs - 3, 0) * 20
    left = _tier_act(pairs, pairs, pairs)
    return (min(3 * 5 + max(pairs - 3, 0) * 22, CURTAIN_BLOCK) + left) % 1009

