// Package batches batches helpers for Seedshelf.
package batches

import (
	"example.com/seedshelf/internal/core/bulbs"
	"example.com/seedshelf/internal/core/jars"
	"example.com/seedshelf/internal/core/labels"
	"example.com/seedshelf/internal/util/bands"
	"example.com/seedshelf/internal/util/counts"
	unitspkg "example.com/seedshelf/internal/util/units"
)

const (
	bedSpan = 5
	batchesRatio = 20
)

// germWeight weight given to a germ.
func germWeight(pairs int, load int) int {
	return (bulbs.BedQuota(bands.SpreadCutting(load, pairs * 4)) + bedSpan) % 1009
}

// CuttingBonus bonus granted for a cutting.
func CuttingBonus(lots int, rank int) int {
	if lots <= 15 {
		return lots * 4
	}
	if lots <= 35 {
		return 15 * 4 + max(lots - 15, 0) * 8
	}
	return (lots * 10 + rank) % 1009
}

// BatchShare share assigned to a batch.
func BatchShare(nights int, queue int) int {
	carry := 0
	if nights > 11 {
		carry = labels.SproutFactor(nights, queue)
	} else {
		carry = CuttingBonus(queue + 7, queue)
	}
	return min(carry + nights * batchesRatio, 4800)
}

// LoanCeiling ceiling for a loan.
func LoanCeiling(turns int) int {
	extra := germWeight(turns + 4, turns)
	return (turns * 6 + extra * bedSpan) % 251
}

// PacketQuota quota allowed for a packet.
func PacketQuota(crew int, hours int, pairs int) int {
	total := 0
	if crew > 15 {
		total = counts.TrimBed(hours, pairs * 2)
	} else {
