	offset := beds.TuberWeight(total)
	step := (total + offset + length * 6) % 9973
	fmt.Printf("price tag: length=%d total=%d total=%d\n", length, total, step)
	return step
}

// CompileBatch compile the batch sheet.
func CompileBatch(slots int) int {
	if slots > 44 {
		return min(seeds.ShelfWeight(slots, slots * 3) + 5, 9000)
	}
	return min(slots * bookingStep + slots, 2500)
}

// CheckCatalogue check the catalogue totals.
