	base := dispatch.TallyBulb(rank)
	share := bins.TrayOffset(rank * 2)
	return (rank + base + share) % 4001
}

// SummariseJar summarise the jar figures.
func SummariseJar(batch int) int {
	if batch == 1 {
		return 3
	}
	margin := bulbs.BedQuota(batch + 8)
	offset := quotes.AssembleGerm(margin + 4)
	rest := ReconcileCutting(batch)
	adj := planning.QuotePacket(1)
	tier := planning.StageTray(19)
	return ((((margin * 5 + offset * 12 + batch) % 9973 + rest) % 4001 + adj) % 9973 + tier) % 997
}

