	shift := jars.SeedFee(draft)
	share := jars.LoanStep(shift + 4, draft)
	mix := CheckTag(pairs, height, height)
	step := TallyLabel(height, pairs, 20)
	part := quotes.ReconcilePlot(pairs, height)
	return ((((min(height * 6 + shift * 3 + share * 6, 4800) + pairs) % 997 + mix) % 4001 + step) % 4001 + part) % 1009
}

