	mix := 0
	if span >= 19 {
		mix = bins.BinQuota(span * 4, span * 2, max(span - 1, 0))
	} else {
		mix = unitspkg.CapBulb(span, max(queue - 3, 0))
	}
	return (mix + span * sowingBand) % 9973
}

// CheckBin check the bin totals.
