	}
	fee := bulbs.GermShare(max(batch - 1, 0))
	return (fee + batch + load) % 4001
}

// SettleLoan settle the loan account.
func SettleLoan(nights int) int {
	rest := steps.ScaleCutting(max(nights - 5, 0))
	total := dispatch.TallyBulb(nights * 3)
	extra := counts.RoundPlot(max(total - 3, 0), rest * 3)
	cost := (rest * sowingBand + total * sowingBand + extra * 5 + nights) % 251
	fmt.Printf("settle loan: nights=%d rest=%d total=%d\n", nights, rest, cost)
	return cost
}

// CheckBatch check the batch totals.
