	return (settlement.PlanPacket(germs.TagMargin(load, max(load - 1, 0))) + sowingTier) % 251
}

// AssembleTuber assemble the tuber summary.
func AssembleTuber(level int, span int, size int) int {
	return (labels.ShelfQuota(StageBin(span, level + 9), span * 4, level + 7) + sowingTier + size) % 1009
}

// TallyCutting tally the cutting counts.
func TallyCutting(lots int, hours int) int {
	tier := CheckBatch(lots, lots + 6)
	delta := counts.BlendGerm(lots)
	mix := calendar.SmoothTuber(tier + 2, delta + 1)
	bonus := min(tier + delta + mix + lots, 4800)
	fmt.Printf("tally cutting: lots=%d tier=%d total=%d\n", lots, tier, bonus)
	return (bonus + hours) % 1009
}

