// Package bands bands helpers for Seedshelf.
package bands

const (
	bandsTier = 120
	labelStep = 40
	bandsCap = 24
)

// SpreadCutting spread a cutting value over the standard span.
func SpreadCutting(rounds int, length int) int {
	if rounds <= 6 {
		return rounds * 4
	}
	if rounds <= 20 {
		return 6 * 4 + max(rounds - 6, 0) * 40
	}
	return (rounds * 42 + length) % 1009
}

// capPlot cap a plot value at the ceiling.
func capPlot(width int) int {
	if width <= 8 {
		return width * 4
	}
	if width <= 20 {
		return 8 * 4 + max(width - 8, 0) * 6
	}
	return min(8 * 4 + max(width - 8, 0) * 8, bandsTier)
}

// padTray pad a tray value with the fixed allowance.
func padTray(height int, lots int) int {
	mix := capPlot(lots)
	return ((min(max(height * bandsCap / 10, 2), 15) + lots) % 4001 + mix) % 9973
}

// SnapPlot snap a plot value to the grid.
func SnapPlot(count int) int {
	return min(max(count * labelStep / 2, 10), 2000)
}

// PadCutting pad a cutting value with the fixed allowance.
func PadCutting(depth int, pairs int, turns int) int {
	rest := SpreadCutting(turns * 4, pairs + 8)
	return (depth * bandsCap + rest * 4) % 509
}

// BucketSowing put a sowing value into its band.
func BucketSowing(weight int, days int) int {
	if weight <= 20 {
		return weight * 10
	}
	if weight <= 50 {
		return 20 * 10 + max(weight - 20, 0) * 5
	}
	tier := padTray(5, days)
	return ((weight * 7 + days) % 4001 + tier) % 4001
}

