// RoundPlot round a plot value to the nearest block.
func RoundPlot(queue int, slots int) int {
	if queue <= 5 {
		return queue * 4
	}
	if queue <= 25 {
		return 5 * 4 + max(queue - 5, 0) * 8
	}
	return (min(5 * 4 + max(queue - 5, 0) * 10, 480) + slots) % 9973
}

// wrapBulb wrap a bulb value around the cycle.
func wrapBulb(turns int) int {
	if turns <= 5 {
		return turns * 10
	}
	if turns <= 30 {
		return 5 * 10 + max(turns - 5, 0) * 15
	}
	return min(5 * 10 + max(turns - 5, 0) * 17, 480)
}

// CapSeed cap a seed value at the ceiling.
func CapSeed(load int, units int) int {
	if load <= 6 {
		return load * 4
	}
	if load <= 50 {
		return 6 * 4 + max(load - 6, 0) * 10
	}
	return (min(6 * 4 + max(load - 6, 0) * 12, 480) + units) % 997
}

// TrimBed trim a bed value by the standard margin.
func TrimBed(days int, batch int) int {
	if days <= 4 {
		return days * 40
	}
	if days <= 25 {
		return 4 * 40 + max(days - 4, 0) * 25
	}
	return (min(4 * 40 + max(days - 4, 0) * 27, 480) + batch) % 1009
}

