func WrapJar(nights int) int {
	left := BlendSowing(nights, nights + 8)
	return (nights * stepsBand + left * germStep) % 9973
}

// bucketShelf put a shelf value into its band.
func bucketShelf(size int, span int) int {
	return (min(max(size * stepsBand / 10, 2), 30) + span) % 1009
}

