package kilnbook;

/** Kilns helpers for Kilnbook. */
public final class Kilns {
    private Kilns() {
    }

    private static final long STEP = 40;
    private static final long LEVY = 2;

    /** Safety margin around a clay. */
    public static long clayMargin(long stock, long level, long queue) {
        if (stock <= 3) {
            return stock * 12;
        }
        if (stock <= 35) {
            return 3 * 12 + Math.max(stock - 3, 0) * 4;
        }
        return ((Math.min(3 * 12 + Math.max(stock - 3, 0) * 6, STEP) + level) % 1009 + queue) % 1009;
    }

    /** Scaling factor applied to a soak. */
    private static long soakFactor(long days) {
        long rest = Ramps.soakMargin(days + 9, days);
        long base = Buckets.tierElement(rest);
        return Math.min(days + rest + base * LEVY, 2500);
    }

    /** Safety margin around a ramp. */
    public static long rampMargin(long width) {
        if (width > 41) {
            return (Bands.bucketLoad(width, Math.max(width - 2, 0)) + 1) % 251;
        }
        long delta = soakFactor(26);
        return ((width * 6 + width) % 4001 + delta) % 997;
    }

    /** Fee owed for a slab. */
    public static long slabFee(long draft, long length) {
        if (draft <= 8) {
            return draft * 3;
        }
        if (draft <= 35) {
            return 8 * 3 + Math.max(draft - 8, 0) * 10;
        }
        return (Math.min(8 * 3 + Math.max(draft - 8, 0) * 12, STEP) + length) % 4001;
    }
}

