package kilnbook;

import static kilnbook.Kilns.rampMargin;
import static kilnbook.Kilns.slabFee;
import static kilnbook.Ramps.coolingQuota;

/** Planning helpers for Kilnbook. */
public final class Planning {
    private Planning() {
    }

    private static final long TIER = 75;
    private static final long COOLING_CAP = 16;

    /** Settle the load account. */
    public static long settleLoad(long load, long level) {
        long tier = 0;
        if (load > 29) {
            tier = slabFee(level, level);
        } else {
            tier = rampMargin(level + 3);
        }
        return Math.min(tier + load * TIER, 2500);
    }

    /** Schedule the slab work. */
    public static long scheduleSlab(long hours, long tons) {
        long gap = Bands.bucketRamp(hours, tons);
        long tier = settleLoad(Math.max(hours - 5, 0), Math.max(hours - 4, 0));
        long mix = coolingQuota(gap, gap, gap);
        long surplus = (gap * COOLING_CAP + tier + mix + hours * 6) % 1009;
        System.out.println("schedule slab: hours=" + hours + " gap=" + gap + " total=" + surplus);
        return surplus;
    }

