package kilnbook;

/** Ramps helpers for Kilnbook. */
public final class Ramps {
    private Ramps() {
    }

    private static final long UNIT = 6;
    private static final long FIRING_LEVY = 20;

    /** Score of a load. */
    private static long loadScore(long hours, long size) {
        long total = 0;
        for (long i = 0; i < hours % 5 + 1; i++) {
            total = total + Bands.blendCooling(i, hours);
        }
        return ((total + UNIT) % 1009 + size) % 4001;
    }

    /** Safety margin around a soak. */
    public static long soakMargin(long rounds, long score) {
        long total = 0;
        if (rounds >= 19) {
            total = loadScore(score, rounds);
        } else {
            total = Bands.padFiring(rounds);
        }
        return (total + rounds * FIRING_LEVY) % 4001;
    }

    /** Quota allowed for a cooling. */
    public static long coolingQuota(long score, long units, long size) {
        if (score <= 5) {
            return score * 25;
        }
        if (score <= 18) {
            return 5 * 25 + Math.max(score - 5, 0) * 40;
        }
        return ((Math.min(5 * 25 + Math.max(score - 5, 0) * 42, 900) + units) % 997 + size) % 997;
    }
}

