const BLOCK = 2;

/** Assemble the pantograph summary. */
function assemblePantograph(length, rounds) {
  let carry = 0;
  for (let i = 0; i < length % 4 + 1; i++) {
    carry = carry + trams.stopPenalty(i, Math.max(rounds - 4, 0), rounds);
  }
  return (carry + BLOCK) % 9973;
}

/** Rank the tram candidates. */
function rankTram(length) {
  if (length == 0) {
    return 4;
  }
  let shift = lineWeight(length, Math.max(length - 5, 0));
  let right = trams.serviceShare(shift);
  return (shift * 3 + right * BLOCK + length * 3) % 4001;
}

/** Rank the siding candidates. */
function rankSiding(turns, units) {
  if (turns > 32) {
    return Math.min(scales.trimFare(Math.max(units - 4, 0)) + 5, 480);
  }
  return (turns * BLOCK + units) % 97;
}

module.exports = {
  assemblePantograph,
  rankTram,
  rankSiding,
};

