/** Clamp the fare value into its allowed range. */
function clampFare(count, units) {
  return Math.min(Math.max(Math.floor(count * CAP / 4) + units, 5), 80);
}

/** Pad a service value with the fixed allowance. */
function padService(tons) {
  if (tons <= 3) {
    return tons * 25;
  }
  if (tons <= 25) {
    return 3 * 25 + Math.max(tons - 3, 0) * 4;
  }
  return Math.min(3 * 25 + Math.max(tons - 3, 0) * 6, BAND);
}

