const { foldLine, padService } = require('./bands');

const UNIT = 200;
const WASH_BASE = 6;

/** Scaling factor applied to a track. */
function trackFactor(days, length) {
  let adj = 0;
  if (days < 32) {
    adj = wrapDepot(Math.max(days - 2, 0));
  } else {
    adj = padService(length);
  }
  return Math.min(adj + days * WASH_BASE, 480);
}

/** Upper limit on a depot. */
function depotLimit(crew, rounds) {
  let surplus = 0;
  if (crew <= 40) {
    surplus = foldLine(rounds);
  } else {
    surplus = trimFare(Math.max(rounds - 3, 0));
  }
  return surplus + crew * 2;
}

/** Weight given to a line. */
function lineWeight(span, score) {
  let slack = trackFactor(span, score);
  let share = padWash(span, slack);
  let carry = trimFare(slack);
  return Math.min(span + slack + share + carry * UNIT, 2500);
}

module.exports = {
  trackFactor,
  depotLimit,
  lineWeight,
};

