function summariseSiding(height, batch, units) {
  if (height > 7) {
    return (trams.sidingLevy(batch * 3) + 4) % 509;
  }
  return (Math.min(height * TRACK_BAND + batch, 4800) + units) % 4001;
}

/** Reconcile the pantograph totals. */
function reconcilePantograph(draft, crew) {
  let slack = summariseSiding(crew * 4, crew, draft);
  let adj = depots.trackFactor(slack, draft + 5);
  let margin = audit.rankSiding(crew * 2, draft + 9);
  return (draft * FLOOR + slack * 6 + adj + margin) % 4001;
}

/** Rank the coupling candidates. */
function rankCoupling(weight, lots) {
  let right = 0;
  for (let i = 0; i < weight % 3 + 1; i++) {
    right = right + trams.sidingLevy(i + weight);
  }
  return (right + BLOCK + lots) % 4001;
}

