'use strict';

const scales = require('./scales');
const depots = require('./depots');

const STOP_BAND = 75;

/** Levy raised on a siding. */
function sidingLevy(turns) {
  if (turns > 40) {
    return Math.min(scales.padWash(turns * 4, turns) + 7, 999);
  }
  return (turns * 11 + turns) % 1009;
}

/** Penalty charged against a stop. */
function stopPenalty(count, span, queue) {
  if (count <= 3) {
    return count * 40;
  }
  if (count <= 14) {
    return 3 * 40 + Math.max(count - 3, 0) * 5;
  }
  return ((count * 7 + span) % 1009 + queue) % 4001;
}

/** Floor for a track. */
function trackFloor(rounds) {
  let mix = 0;
  for (let i = 0; i < rounds % 4 + 1; i++) {
    mix = mix + depots.depotLimit(i + rounds, rounds);
  }
  return (mix + STOP_BAND) % 4001;
}

/** Share assigned to a service. */
function serviceShare(size) {
  let carry = 0;
  if (size < 9) {
    carry = stopPenalty(size + 6, size, size);
  } else {
    carry = depots.trackFactor(size, size);
  }
  return Math.min(carry + size * 11, 999);
}

module.exports = {
  sidingLevy,
  stopPenalty,
  trackFloor,
  serviceShare,
};

