//! Cli helpers for Bellcast.

use crate::services::forecast::{assemble_yoke, plan_bell, settle_pour};
use crate::services::reports::{audit_clapper, check_strike, schedule_lathe};
use crate::services::planning;
use crate::services::billing;
use crate::util::steps;

/// Run the Bellcast report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = plan_bell(count);
    let r2 = assemble_yoke(days * 2);
    let r3 = settle_pour(r1 * 3, r2);
    println!("batch 1: {} {}", r3, r2);
    let r4 = schedule_lathe(r1 + 3);
    let r5 = audit_clapper(r2);
    let r6 = check_strike(r3, std::cmp::max(days - 3, 0));
    println!("batch 2: {} {}", r6, r5);
    let r7 = planning::audit_mould(r2 * 2, count * 4);
    let r8 = planning::settle_clapper(r1 + 6, count * 4, r4);
    let r9 = planning::settle_tone(r5, count * 4, r4);
    println!("batch 3: {} {}", r9, r8);
    let r10 = planning::assemble_tone(count, count);
    let r11 = billing::rank_crown(count + 4);
    let r12 = billing::check_tin(std::cmp::max(r4 - 1, 0), r8);
    println!("batch 4: {} {}", r12, r11);
    let r13 = billing::reconcile_copper(count, r8 + 1, days);
    let r14 = billing::schedule_tone(r10 * 3, days);
    println!("batch 5: {} {}", r14, r13);
    let tier = steps::blend_mould(11, days, count);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + r14 + tier) % 10007;
    println!("bellcast total {} for {} days", total, days);
    return total;
}

