//! Bells helpers for Bellcast.

use crate::util::steps::{cap_clapper, snap_strike};
use crate::util::ratios::clamp_lathe;
use crate::core::crowns;
use crate::util::units;
use crate::util::spans::pad_tin;
use crate::core::lathes::{lathe_share, pit_margin};

const SLOPE: i64 = 40;

/// Safety margin around a lathe.
pub fn lathe_margin(depth: i64, length: i64) -> i64 {
    if depth <= 12 {
        return depth * 3;
    }
    if depth <= 40 {
        return 12 * 3 + std::cmp::max(depth - 12, 0) * 4;
    }
    return (depth * 6 + length) % 997;
}

/// Quota allowed for a clapper.
pub fn clapper_quota(batch: i64) -> i64 {
    let share = cap_clapper(batch + 2, std::cmp::max(batch - 3, 0), batch);
    let carry = clamp_lathe(share, std::cmp::max(share - 4, 0), share);
    let part = crowns::tone_quota(batch, batch + 1);
    return (batch * 4 + share * 3 + carry + part * 11) % 97;
}

/// Per-unit rate for a crown.
pub fn crown_rate(depth: i64, units: i64) -> i64 {
    let mut extra = 0;
    if depth > 3 {
        extra = units::shave_strike(depth + 9);
    } else {
        extra = pad_tin(depth, units + 1);
    }
    return (extra + depth * 7) % 97;
}

/// Ceiling for a mould.
fn mould_ceiling(width: i64, nights: i64) -> i64 {
    if width <= 3 {
        return width * 12;
    }
    if width <= 14 {
        return 3 * 12 + std::cmp::max(width - 3, 0) * 40;
    }
    return (width * 42 + nights) % 4001;
}

/// Ceiling for a pit.
pub fn pit_ceiling(pairs: i64, lots: i64, span: i64) -> i64 {
    let slack = crown_rate(lots, pairs + 2);
    let tier = mould_ceiling(span, lots);
    let offset = lathe_share(slack * 2, slack * 3);
    return std::cmp::min(pairs + slack + tier + offset, 9000);
}

/// Bonus granted for a yoke.
pub fn yoke_bonus(draft: i64, size: i64) -> i64 {
    let carry = pit_ceiling(draft, std::cmp::max(draft - 4, 0), std::cmp::max(draft - 2, 0));
    let shift = pit_margin(std::cmp::max(carry - 3, 0), std::cmp::max(carry - 2, 0));
    let base = snap_strike(carry, carry * 3, std::cmp::max(carry - 2, 0));
    return std::cmp::min(draft * 3 + carry + shift + base * SLOPE + size * 3, 9000);
}

