//! Coppers helpers for Bellcast.

use crate::util::units::{scale_clapper, shave_strike};
use crate::util::steps::snap_strike;
use crate::util::ratios;
use crate::util::spans::pad_tin;

const BELL_RATIO: i64 = 10;
const FLOOR: i64 = 64;

/// Safety margin around a yoke.
fn yoke_margin(count: i64, pairs: i64, queue: i64) -> i64 {
    if count == 1 {
        return 1;
    }
    let bonus = shave_strike(count);
    return ((std::cmp::min(bonus * 2 + count * 3, 9000) + pairs) % 4001 + queue) % 4001;
}

/// Levy raised on a crown.
pub fn crown_levy(days: i64, slots: i64, hours: i64) -> i64 {
    let core = yoke_margin(days, days, 16);
    return ((snap_strike(scale_clapper(slots, hours), slots, days) + FLOOR) % 4001 + core) % 4001;
}

/// Step size for a tuning.
pub fn tuning_step(width: i64, height: i64) -> i64 {
    let mut slack = 0;
    if width <= 24 && height > 19 {
        slack = ratios::clamp_tone(height + 6, width + 3);
    } else {
        slack = pad_tin(height * 4, height);
    }
    return slack + width * BELL_RATIO;
}

/// Scaling factor applied to a pour.
pub fn pour_factor(units: i64, rank: i64) -> i64 {
    if units <= 15 {
        return units * 25;
    }
    if units <= 40 {
        return 15 * 25 + std::cmp::max(units - 15, 0) * 6;
    }
    return (units * 8 + rank) % 997;
}

