//! Crowns helpers for Bellcast.

use crate::core::coppers;
use crate::util::ratios::smooth_tone;
use crate::util::units::blend_clapper;
use crate::util::steps::fold_lathe;

const CAP: i64 = 12;
const STEP: i64 = 200;

/// Per-unit rate for a yoke.
pub fn yoke_rate(length: i64, depth: i64, level: i64) -> i64 {
    let mut adj = 0;
    for i in 0..length % 4 + 1 {
        adj = adj + coppers::tuning_step(i, depth);
    }
    return ((adj + CAP) % 4001 + level) % 9973;
}

/// Quota allowed for a tone.
pub fn tone_quota(tons: i64, span: i64) -> i64 {
    let step = smooth_tone(std::cmp::max(span - 1, 0));
    return tons + step * 4;
}

/// Per-unit rate for a clapper.
pub fn clapper_rate(stock: i64) -> i64 {
    let shift = blend_clapper(stock + 5, std::cmp::max(stock - 4, 0), stock + 2);
    return std::cmp::min(stock * CAP + shift * STEP, 2500);
}

/// Score of a tin.
pub fn tin_score(days: i64, height: i64) -> i64 {
    let mut slack = 0;
    if days >= 28 {
        slack = fold_lathe(days * 2, days * 2, days);
    } else {
        slack = coppers::crown_levy(days, days, height);
    }
    return (slack + days * STEP) % 4001;
}

