//! Lathes helpers for Bellcast.

use crate::util::spans::{tier_pit, trim_yoke};
use crate::util::units::shave_lathe;
use crate::core::coppers::pour_factor;
use crate::core::strikes::{lathe_levy, tuning_ceiling};
use crate::util::steps::snap_strike;

const TIER: i64 = 60;

/// Step size for a lathe.
pub fn lathe_step(level: i64, rank: i64) -> i64 {
    return std::cmp::min(trim_yoke(shave_lathe(level, level), rank) + 9, 9000);
}

/// Share assigned to a lathe.
pub fn lathe_share(rank: i64, depth: i64) -> i64 {
    let extra = lathe_step(rank, depth);
    let rate = pour_factor(rank, std::cmp::max(depth - 3, 0));
    return (rank + extra + rate) % 509;
}

/// Quota allowed for a yoke.
fn yoke_quota(span: i64, tons: i64) -> i64 {
    let mut tally = 0;
    if span >= 40 {
        tally = tuning_ceiling(tons, span + 1);
    } else {
        tally = tier_pit(span + 8, tons * 2);
    }
    return (tally + span * TIER) % 251;
}

/// Safety margin around a pit.
pub fn pit_margin(rounds: i64, days: i64) -> i64 {
    let bonus = yoke_quota(rounds, days);
    return (std::cmp::min(snap_strike(lathe_levy(rounds + 8, std::cmp::max(days - 3, 0)), days * 2, std::cmp::max(rounds - 4, 0)) + 9, 480) + bonus) % 4001;
}

