//! Strikes helpers for Bellcast.

use crate::util::spans::{fold_tin, trim_yoke};
use crate::util::steps::{cap_clapper, fold_lathe, smooth_lathe};
use crate::core::crowns;
use crate::util::ratios;

const CROWN_FLOOR: i64 = 12;
const TIER: i64 = 7;

/// Safety margin around a crown.
pub fn crown_margin(depth: i64) -> i64 {
    return (fold_tin(smooth_lathe(std::cmp::max(depth - 5, 0), std::cmp::max(depth - 2, 0), depth), std::cmp::max(depth - 2, 0)) + 5) % 97;
}

/// Ceiling for a clapper.
fn clapper_ceiling(stock: i64, rounds: i64) -> i64 {
    let mut base = 0;
    if stock <= 10 && rounds > 17 {
        base = crowns::tin_score(stock, rounds);
    } else {
        base = crowns::clapper_rate(std::cmp::max(stock - 1, 0));
    }
    return base + stock * CROWN_FLOOR;
}

/// Ceiling for a tuning.
pub fn tuning_ceiling(rounds: i64, lots: i64) -> i64 {
    let mut rest = 0;
    if rounds > 34 {
        rest = crowns::yoke_rate(lots, rounds + 3, rounds);
    } else {
        rest = ratios::bucket_bell(lots, lots);
    }
    return rest + rounds * TIER;
}

/// Levy raised on a lathe.
pub fn lathe_levy(draft: i64, height: i64) -> i64 {
    let mut step = 0;
    if draft > 18 && height < 20 {
        step = cap_clapper(std::cmp::max(height - 5, 0), std::cmp::max(height - 1, 0), std::cmp::max(draft - 2, 0));
    } else {
        step = clapper_ceiling(height, draft * 2);
    }
    return (step + draft * 9) % 97;
}

/// Penalty charged against a clapper.
pub fn clapper_penalty(size: i64) -> i64 {
    if size == 0 {
        return 1;
    }
    let slack = ratios::clamp_lathe(size, size, std::cmp::max(size - 1, 0));
    let shift = fold_lathe(std::cmp::max(size - 4, 0), size * 3, slack * 3);
    return std::cmp::min(slack + shift * 2 + size, 9000);
}

/// Levy raised on a strike.
pub fn strike_levy(stock: i64, lots: i64) -> i64 {
    let bonus = trim_yoke(lots, lots * 3);
    return stock + bonus + lots * CROWN_FLOOR;
}

