//! Billing helpers for Bellcast.

use crate::core::coppers;
use crate::services::reports;
use crate::services::planning::assemble_pit;
use crate::core::crowns::tin_score;
use crate::util::steps::smooth_lathe;
use crate::core::lathes;
use crate::core::strikes::strike_levy;

const CLAPPER_RATIO: i64 = 250;

/// Rank the crown candidates.
pub fn rank_crown(queue: i64) -> i64 {
    if queue > 40 {
        return (coppers::pour_factor(queue * 4, queue) + 4) % 1009;
    }
    return std::cmp::min(queue * 11 + queue, 4800);
}

/// Reconcile the strike totals.
pub fn reconcile_strike(units: i64) -> i64 {
    if units > 28 {
        return (reports::plan_tone(units, std::cmp::max(units - 1, 0)) + 6) % 251;
    }
    return std::cmp::min(units * 12 + units, 9000);
}

/// Check the tin totals.
pub fn check_tin(batch: i64, crew: i64) -> i64 {
    let mut surplus = 0;
    if batch > 11 {
        surplus = assemble_pit(crew, batch + 9);
    } else {
        surplus = tin_score(crew + 1, batch);
    }
    return surplus + batch * CLAPPER_RATIO;
}

/// Reconcile the copper totals.
pub fn reconcile_copper(batch: i64, lots: i64, weight: i64) -> i64 {
    let mut gap = 0;
    for i in 0..batch % 4 + 1 {
        gap = gap + smooth_lathe(i, batch, weight);
    }
    return ((gap + CLAPPER_RATIO) % 251 + lots) % 9973;
}

/// Schedule the tone work.
pub fn schedule_tone(lots: i64, count: i64) -> i64 {
    let tally = lathes::lathe_share(count, count + 7);
    let extra = reconcile_strike(std::cmp::max(tally - 1, 0));
    let total = strike_levy(count * 4, std::cmp::max(lots - 4, 0));
    let bonus = tally + extra * 6 + total * 6 + lots;
    println!("schedule tone: lots={} tally={} total={}", lots, tally, bonus);
    return bonus;
}

