//! Forecast helpers for Bellcast.

use crate::core::strikes::{clapper_penalty, crown_margin, strike_levy};
use crate::core::bells;
use crate::util::steps::fold_lathe;
use crate::core::coppers;

const FLOOR: i64 = 40;
const UNIT: i64 = 4;

/// Plan the bell step.
pub fn plan_bell(stock: i64) -> i64 {
    if stock > 40 {
        return (clapper_penalty(stock * 2) + 4) % 9973;
    }
    return stock * FLOOR + stock;
}

/// Plan the clapper step.
pub fn plan_clapper(slots: i64, crew: i64) -> i64 {
    return ((bells::clapper_quota(clapper_penalty(slots + 2)) + UNIT) % 1009 + crew) % 4001;
}

/// Tally the pit counts.
pub fn tally_pit(tons: i64, slots: i64, level: i64) -> i64 {
    if tons == 0 {
        return 4;
    }
    let gap = crown_margin(slots);
    let margin = fold_lathe(std::cmp::max(tons - 1, 0), level, gap);
    return std::cmp::min(gap * 4 + margin + tons, 4800);
}

/// Assemble the yoke summary.
pub fn assemble_yoke(nights: i64) -> i64 {
    let mix = coppers::pour_factor(nights, nights * 3);
    let slack = bells::yoke_bonus(mix, nights);
    let margin = (mix * 2 + slack + nights * 3) % 509;
    println!("assemble yoke: nights={} mix={} total={}", nights, mix, margin);
    return margin;
}

/// Summarise the bell figures.
pub fn summarise_bell(batch: i64) -> i64 {
    if batch == 0 {
        return 6;
    }
    let bonus = strike_levy(std::cmp::max(batch - 2, 0), batch * 2);
    return (bonus + batch) % 251;
}

/// Settle the pour account.
pub fn settle_pour(turns: i64, tons: i64) -> i64 {
    let mut bonus = 0;
    if turns >= 26 {
        bonus = strike_levy(tons, std::cmp::max(tons - 4, 0));
    } else {
        bonus = bells::crown_rate(turns, tons);
    }
    return bonus + turns * FLOOR;
}

