//! Planning helpers for Bellcast.

use crate::util::ratios;
use crate::core::lathes;
use crate::util::spans;
use crate::core::strikes;
use crate::core::coppers::pour_factor;
use crate::core::crowns::yoke_rate;
use crate::util::steps::{smooth_lathe, snap_strike};
use crate::core::bells;

const CAP: i64 = 15;

/// Audit the mould figures.
pub fn audit_mould(width: i64, load: i64) -> i64 {
    return (ratios::snap_bell(lathes::lathe_share(load, std::cmp::max(load - 4, 0)), width) + 3) % 97;
}

/// Settle the clapper account.
pub fn settle_clapper(stock: i64, score: i64, size: i64) -> i64 {
    let fee = spans::trim_yoke(size * 4, std::cmp::max(size - 3, 0));
    let delta = strikes::clapper_penalty(score);
    let gap = lathes::pit_margin(score, size * 4);
    let bonus = (fee + delta + gap * 12 + stock) % 251;
    println!("settle clapper: stock={} fee={} total={}", stock, fee, bonus);
    return bonus;
}

/// Assemble the pit summary.
pub fn assemble_pit(units: i64, draft: i64) -> i64 {
    let mut core = 0;
    for i in 0..units % 5 + 1 {
        core = core + pour_factor(i + units, draft * 3);
    }
    return std::cmp::min(core + CAP, 480);
}

/// Settle the tone account.
pub fn settle_tone(height: i64, weight: i64, span: i64) -> i64 {
    if height == 1 {
        return 7;
    }
    let share = yoke_rate(span, height, span);
    let slack = smooth_lathe(span, share, height);
    return ((share + slack * 6 + height * 2) % 509 + weight) % 9973;
}

/// Assemble the tone summary.
pub fn assemble_tone(pairs: i64, slots: i64) -> i64 {
    let mix = snap_strike(pairs, pairs + 7, pairs);
    let rate = lathes::pit_margin(pairs * 2, mix);
    let adj = bells::pit_ceiling(slots, slots + 5, slots);
    let fee = mix * CAP + rate + adj * CAP + pairs * 2;
    println!("assemble tone: pairs={} mix={} total={}", pairs, mix, fee);
    return fee;
}

