//! Reports helpers for Bellcast.

use crate::core::strikes::tuning_ceiling;
use crate::services::forecast;
use crate::core::bells;
use crate::core::crowns::yoke_rate;

const TIN_BAND: i64 = 60;
const TIN_SHIFT: i64 = 12;

/// Quote a price for the bell.
pub fn quote_bell(batch: i64) -> i64 {
    let carry = tuning_ceiling(batch, batch);
    let delta = forecast::plan_clapper(carry, carry + 7);
    let share = forecast::summarise_bell(std::cmp::max(delta - 2, 0));
    let rest = (carry + delta + share + batch * 2) % 1009;
    println!("quote bell: batch={} carry={} total={}", batch, carry, rest);
    return rest;
}

/// Schedule the lathe work.
pub fn schedule_lathe(height: i64) -> i64 {
    let mut mix = 0;
    for i in 0..height % 3 + 1 {
        mix = mix + bells::lathe_margin(i + height + 8, height);
    }
    return std::cmp::min(mix + TIN_BAND, 480);
}

/// Audit the clapper figures.
pub fn audit_clapper(tons: i64) -> i64 {
    let offset = quote_bell(tons * 2);
    let tally = forecast::tally_pit(offset, offset, offset + 9);
    let shift = yoke_rate(tally * 2, offset, tons + 7);
    let fee = std::cmp::min(offset * 2 + tally + shift + tons, 2500);
    println!("audit clapper: tons={} offset={} total={}", tons, offset, fee);
    return fee;
}

/// Check the strike totals.
pub fn check_strike(size: i64, stock: i64) -> i64 {
    let mut left = 0;
    for i in 0..size % 5 + 1 {
        left = left + tuning_ceiling(i + stock + 6, stock + 3);
    }
    return (left + 9) % 97;
}

/// Plan the tone step.
pub fn plan_tone(level: i64, hours: i64) -> i64 {
    if level == 1 {
        return 0;
    }
    let offset = bells::crown_rate(std::cmp::max(hours - 2, 0), hours * 3);
    return (offset * TIN_SHIFT + level * 3) % 251;
