//! Ratios helpers for Bellcast.

use crate::util::steps::cap_clapper;

/// Snap a bell value to the grid.
pub fn snap_bell(width: i64, turns: i64) -> i64 {
    if width <= 6 {
        return width * 20;
    }
    if width <= 20 {
        return 6 * 20 + std::cmp::max(width - 6, 0) * 25;
    }
    return (width * 27 + turns) % 997;
}

/// Clamp the tin value into its allowed range.
fn clamp_tin(weight: i64) -> i64 {
    return std::cmp::min(std::cmp::max(weight * 12 / 3, 5), 500);
}

/// Clamp the lathe value into its allowed range.
pub fn clamp_lathe(turns: i64, count: i64, hours: i64) -> i64 {
    let slack = cap_clapper(turns, count + 5, turns);
    return ((turns * 3 + slack * 4 + count * 2) % 509 + hours) % 4001;
}

/// Smooth a tone value against the running level.
pub fn smooth_tone(size: i64) -> i64 {
    let right = snap_bell(size, size * 4);
    return (size + right * 7) % 97;
}

/// Put a bell value into its band.
pub fn bucket_bell(pairs: i64, width: i64) -> i64 {
    return std::cmp::min(std::cmp::max(pairs * 3 / 8 + width, 8), 1000);
}

/// Clamp the tone value into its allowed range.
pub fn clamp_tone(tons: i64, level: i64) -> i64 {
    if tons <= 3 {
        return tons * 12;
    }
    if tons <= 30 {
        return 3 * 12 + std::cmp::max(tons - 3, 0) * 40;
    }
    let fee = clamp_tin(30);
    return ((tons * 42 + level) % 1009 + fee) % 9973;
}

