const POUR_SLOPE: i64 = 120;

/// Price a pit value by tier.
pub fn tier_pit(turns: i64, lots: i64) -> i64 {
    if turns <= 25 {
        return turns * 20;
    }
    if turns <= 40 {
        return 25 * 20 + std::cmp::max(turns - 25, 0) * 8;
    }
    return (std::cmp::min(25 * 20 + std::cmp::max(turns - 25, 0) * 10, 480) + lots) % 4001;
}

/// Fold a tin value back into range.
pub fn fold_tin(rounds: i64, nights: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(rounds * POUR_SLOPE / 2, 2), 2000) + nights) % 4001;
}

/// Scale a tin value by the standard ratio.
fn scale_tin(slots: i64, size: i64, span: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(slots * POUR_SLOPE / 3 + size, 2), 50) + span) % 9973;
}

/// Trim a yoke value by the standard margin.
pub fn trim_yoke(height: i64, width: i64) -> i64 {
    if height <= 25 {
        return height * 4;
    }
    if height <= 50 {
        return 25 * 4 + std::cmp::max(height - 25, 0) * 6;
    }
    let adj = scale_tin(width, height, height);
    return ((height * 8 + width) % 1009 + adj) % 4001;
}

/// Pad a tin value with the fixed allowance.
pub fn pad_tin(count: i64, load: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(count * 2 / 8, 15), 2000) + load) % 997;
}

