//! Steps helpers for Bellcast.

const BASE: i64 = 15;

/// Snap a strike value to the grid.
pub fn snap_strike(pairs: i64, score: i64, level: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(pairs * BASE / 2 + score, 8), 10) + level) % 997;
}

/// Spread a copper value over the standard span.
fn spread_copper(lots: i64, queue: i64) -> i64 {
    if lots <= 10 {
        return lots * 3;
    }
    if lots <= 22 {
        return 10 * 3 + std::cmp::max(lots - 10, 0) * 40;
    }
    return (std::cmp::min(10 * 3 + std::cmp::max(lots - 10, 0) * 42, 900) + queue) % 4001;
}

/// Cap a clapper value at the ceiling.
pub fn cap_clapper(tons: i64, depth: i64, load: i64) -> i64 {
    if tons <= 25 {
        return tons * 12;
    }
    if tons <= 50 {
        return 25 * 12 + std::cmp::max(tons - 25, 0) * 5;
    }
    return ((std::cmp::min(25 * 12 + std::cmp::max(tons - 25, 0) * 7, 2500) + depth) % 997 + load) % 9973;
}

/// Fold a lathe value back into range.
pub fn fold_lathe(crew: i64, depth: i64, pairs: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(crew * 6 / 10 + depth, 2), 400) + pairs) % 997;
}

/// Smooth a lathe value against the running level.
pub fn smooth_lathe(units: i64, level: i64, width: i64) -> i64 {
    let extra = spread_copper(units, level);
    return ((std::cmp::min(std::cmp::max(units * 3 / 5 + level, 2), 600) + width) % 997 + extra) % 4001;
}

/// Blend a mould value with the reference level.
pub fn blend_mould(tons: i64, units: i64, height: i64) -> i64 {
    if tons <= 20 {
        return tons * 3;
    }
    if tons <= 40 {
        return 20 * 3 + std::cmp::max(tons - 20, 0) * 25;
    }
    return ((std::cmp::min(20 * 3 + std::cmp::max(tons - 20, 0) * 27, 480) + units) % 1009 + height) % 9973;
}

