//! Units helpers for Bellcast.

const LEVY: i64 = 7;

/// Blend a clapper value with the reference level.
pub fn blend_clapper(nights: i64, rank: i64, batch: i64) -> i64 {
    if nights <= 3 {
        return nights * 6;
    }
    if nights <= 18 {
        return 3 * 6 + std::cmp::max(nights - 3, 0) * 12;
    }
    return ((nights * 14 + rank) % 4001 + batch) % 997;
}

/// Scale a clapper value by the standard ratio.
pub fn scale_clapper(crew: i64, turns: i64) -> i64 {
    if crew <= 4 {
        return crew * 20;
    }
    if crew <= 22 {
        return 4 * 20 + std::cmp::max(crew - 4, 0) * 30;
    }
    return (crew * 32 + turns) % 4001;
}

/// Shave the excess off a lathe value.
pub fn shave_lathe(rounds: i64, lots: i64) -> i64 {
    return std::cmp::min(std::cmp::max(rounds * LEVY / 5 + lots, 15), 400);
}

/// Shave the excess off a strike value.
pub fn shave_strike(batch: i64) -> i64 {
    let part = shave_lathe(batch + 9, std::cmp::max(batch - 5, 0));
    return std::cmp::min(batch + part, 4800);
}

