'use strict';

const { dispatchBatch, reconcileAging, settleBrine } = require('./services/forecast');
const booking = require('./services/booking');
const { compileBatch, planCrate, priceLabel } = require('./services/quotes');
const { assembleCrate, quoteBrine, rankCurd, summariseCurd } = require('./services/settlement');
const { crateMargin } = require('./core/humidities');
const { padRind } = require('./util/scales');

/** Run the Cavelog report for a batch size and a number of days. */
function run(count, days) {
  let r1 = reconcileAging(days, days);
  let r2 = dispatchBatch(r1);
  let r3 = settleBrine(r2, count * 3);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = booking.rankWheel(r1);
  let r5 = booking.quoteCrate(r4, r2);
  let r6 = booking.scheduleLabel(r1);
  console.log(`batch 2: ${r6} ${r5}`);
  let r7 = planCrate(r6 * 3, r1 * 2);
  let r8 = compileBatch(Math.max(r5 - 4, 0));
  let r9 = priceLabel(r6 * 4, Math.max(r2 - 4, 0));
  console.log(`batch 3: ${r9} ${r8}`);
  let r10 = rankCurd(r7 + 2, days);
  let r11 = assembleCrate(r1, Math.max(r3 - 5, 0));
  let r12 = quoteBrine(r1, r7);
  console.log(`batch 4: ${r12} ${r11}`);
  let r13 = summariseCurd(r9, r3);
  console.log(`batch 5: ${r13} ${r12}`);
  let rate = crateMargin(count, count, days);
  let slack = padRind(days);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + rate + slack) % 10007;
  console.log(`cavelog total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

