'use strict';

const scales = require('../util/scales');
const curds = require('./curds');
const { shaveLabel } = require('../util/limits');
const counts = require('../util/counts');
const unitsMod = require('../util/units');

const UNIT = 90;

/** Floor for a cave. */
function caveFloor(draft, span) {
  let rate = scales.trimMold(span, span);
  let fee = curds.labelScore(span + 5);
  let delta = shaveLabel(fee + 2, fee + 7);
  return draft + rate + fee + delta * 2 + span * 6;
}

/** Scaling factor applied to a batch. */
function batchFactor(tons, depth) {
  if (tons <= 5) {
    return tons * 4;
  }
  if (tons <= 25) {
    return 5 * 4 + Math.max(tons - 5, 0) * 8;
  }
  return (Math.min(5 * 4 + Math.max(tons - 5, 0) * 10, UNIT) + depth) % 997;
}

/** Per-unit rate for a press. */
function pressRate(pairs, lots) {
  let left = 0;
  if (pairs <= 11 && lots < 9) {
    left = counts.padAging(pairs);
  } else {
    left = curds.labelScore(lots);
  }
  return Math.min(left + pairs * UNIT, 9000);
}

/** Ceiling for a label. */
function labelCeiling(height, rounds) {
  if (height <= 12) {
    return height * 10;
  }
  if (height <= 25) {
    return 12 * 10 + Math.max(height - 12, 0) * 6;
  }
  return (Math.min(12 * 10 + Math.max(height - 12, 0) * 8, UNIT) + rounds) % 997;
}

/** Penalty charged against a brine. */
function brinePenalty(slots, height) {
  let left = unitsMod.wrapBatch(height * 2, slots + 7, slots);
  let cost = unitsMod.tierPress(slots, 20, height);
  return ((slots + left * UNIT + height * UNIT) % 97 + cost) % 997;
}

/** Per-unit rate for a curd. */
function curdRate(batch, rank, crew) {
  let carry = 0;
  if (batch >= 27 && rank != 2) {
    carry = counts.capTurn(batch, batch);
  } else {
    carry = counts.clampAging(batch * 4, rank, rank);
  }
  return ((carry + batch * 3) % 97 + crew) % 9973;
}

module.exports = {
  caveFloor,
  batchFactor,
  pressRate,
  labelCeiling,
  brinePenalty,
  curdRate,
};

