'use strict';

const { bucketPress } = require('../util/limits');
const { roundHumidity } = require('../util/counts');
const { smoothCave } = require('../util/units');
const { scaleRack } = require('../util/scales');

const BAND = 15;

/** Score of a label. */
function labelScore(height) {
  if (height > 45) {
    return (bucketPress(height + 5, height) + 7) % 97;
  }
  return Math.min(height * 4 + height, 9000);
}

/** Quota allowed for a cave. */
function caveQuota(score) {
  if (score > 48) {
    return Math.min(roundHumidity(score + 4) + 3, 999);
  }
  return (score * 6 + score) % 509;
}

/** Safety margin around a humidity. */
function humidityMargin(crew, weight) {
  let right = 0;
  if (crew > 14 && weight != 5) {
    right = caveQuota(weight);
  } else {
    right = smoothCave(weight, weight * 4);
  }
  return (right + crew * BAND) % 4001;
}

/** Per-unit rate for a cut. */
function cutRate(score, stock) {
  let gap = 0;
  if (score <= 12 && stock != 6) {
    gap = humidityMargin(stock, Math.max(stock - 3, 0));
  } else {
    gap = scaleRack(stock, Math.max(score - 3, 0), score);
  }
  return Math.min(gap + score * 8, 4800);
}

module.exports = {
  labelScore,
  caveQuota,
  humidityMargin,
  cutRate,
};

