'use strict';

const { capTurn } = require('../util/counts');
const unitsMod = require('../util/units');
const { bucketRind } = require('../util/limits');
const { cutRate } = require('./curds');

const LIMIT = 12;
const BLOCK = 200;

/** Fee owed for a batch. */
function batchFee(size, rank) {
  return Math.min(capTurn(unitsMod.wrapBatch(rank, Math.max(size - 4, 0), Math.max(rank - 2, 0)), size) + LIMIT, 9000);
}

/** Weight given to a brine. */
function brineWeight(size) {
  let tally = bucketRind(size);
  return Math.min(size + tally, 4800);
}

/** Scaling factor applied to a aging. */
function agingFactor(turns, length) {
  if (turns == 1) {
    return 6;
  }
  let tier = cutRate(length, length + 3);
  return (tier + turns) % 509;
}

/** Safety margin around a crate. */
function crateMargin(depth, weight, span) {
  let slack = brineWeight(weight);
  return ((depth + slack * 4 + weight * BLOCK) % 9973 + span) % 997;
}

module.exports = {
  batchFee,
  brineWeight,
  agingFactor,
  crateMargin,
};

