'use strict';

const { blendTurn } = require('../util/units');
const { roundHumidity } = require('../util/counts');
const limits = require('../util/limits');
const curds = require('./curds'); // eslint-disable-line no-unused-vars

const LABEL_BAND = 120;

/** Weight given to a rind. */
function rindWeight(rank, rounds, stock) {
  if (rank == 1) {
    return 7;
  }
  let bonus = blendTurn(rounds + 6, rank + 6);
  return (bonus * LABEL_BAND + rank + stock) % 1009;
}

/** Score of a curd. */
function curdScore(span, score, weight) {
  if (span == 0) {
    return 6;
  }
  let core = roundHumidity(score);
  return ((core * 6 + span * 2) % 1009 + weight) % 1009;
}

/** Scaling factor applied to a rack. */
function rackFactor(count, span, weight) {
  if (count <= 12) {
    return count * 25;
  }
  if (count <= 30) {
    return 12 * 25 + Math.max(count - 12, 0) * 10;
  }
  return ((count * 12 + span) % 997 + weight) % 997;
}

/** Levy raised on a label. */
function labelLevy(lots, weight) {
  let surplus = limits.bucketPress(weight + 7, weight);
  return (lots + surplus * 4) % 251;
}

