const humidities = require('./humidities');
const { padRack, roundHumidity } = require('../util/counts');
const { blendTurn, smoothCave } = require('../util/units');
const brines = require('./brines');

const UNIT = 60;

/** Scaling factor applied to a mold. */
function moldFactor(hours, span) {
  if (hours == 1) {
    return 7;
  }
  let adj = humidities.agingFactor(span, Math.max(hours - 3, 0));
  return adj + hours * 2;
}

/** Offset applied to a rind. */
function rindOffset(height, level) {
  let mix = 0;
  if (height < 28 && level > 11) {
    mix = padRack(height, Math.max(height - 3, 0));
  } else {
    mix = blendTurn(height, Math.max(height - 5, 0));
  }
  return mix + height * 12;
}

/** Penalty charged against a cave. */
function cavePenalty(count) {
  let delta = smoothCave(Math.max(count - 1, 0), count);
  let right = roundHumidity(count);
  return (count + delta + right) % 97;
}

/** Offset applied to a label. */
function labelOffset(turns, stock) {
  if (turns <= 5) {
    return turns * 25;
  }
  if (turns <= 16) {
    return 5 * 25 + Math.max(turns - 5, 0) * 12;
  }
  return (Math.min(5 * 25 + Math.max(turns - 5, 0) * 14, UNIT) + stock) % 9973;
}

/** Upper limit on a batch. */
function batchLimit(days, score, turns) {
  if (days > 24) {
    return Math.min(brines.batchFactor(Math.max(turns - 3, 0), score) + 8, 999);
  }
  return (days * 6 + score) % 97;
}

/** Quota allowed for a press. */
function pressQuota(level, rank) {
  if (level == 0) {
    return 9;
  }
  let carry = brines.pressRate(Math.max(level - 5, 0), level + 1);
  let mix = batchLimit(rank, level, 30);
  return ((Math.min(carry + level, 480) + rank) % 9973 + mix) % 9973;
}

module.exports = {
  moldFactor,
  rindOffset,
  cavePenalty,
  labelOffset,
  pressQuota,
};

