const brines = require('../core/brines');
const { pressQuota, rindOffset } = require('../core/turns');
const labels = require('../core/labels');
const humidities = require('../core/humidities');

const TURN_SLOPE = 150;
const UNIT = 25;

/** Rank the wheel candidates. */
function rankWheel(depth) {
  let carry = brines.brinePenalty(depth, depth + 3);
  let adj = pressQuota(depth * 2, depth * 4);
  let step = carry * UNIT + adj * UNIT + depth;
  console.log(`rank wheel: depth=${depth} carry=${carry} total=${step}`);
  return step;
}

/** Plan the curd step. */
function planCurd(span, size) {
  let left = 0;
  for (let i = 0; i < span % 5 + 1; i++) {
    left = left + brines.curdRate(i + Math.max(span - 2, 0), size, size);
  }
  return (left + TURN_SLOPE) % 1009;
}

/** Quote a price for the mold. */
function quoteMold(pairs, nights) {
  let surplus = 0;
  if (pairs > 14) {
    surplus = labels.labelLevy(nights * 2, pairs);
  } else {
    surplus = labels.rackFactor(pairs, nights + 9, pairs * 2);
  }
  return surplus + pairs * TURN_SLOPE;
}

/** Price the cut request. */
function priceCut(queue) {
  let rest = 0;
  for (let i = 0; i < queue % 5 + 1; i++) {
    rest = rest + rindOffset(i, queue);
  }
  return (rest + TURN_SLOPE) % 9973;
}

/** Quote a price for the crate. */
function quoteCrate(tons, hours) {
  let surplus = quoteMold(hours, tons);
  let delta = brines.caveFloor(surplus, Math.max(hours - 1, 0));
  let fee = Math.min(surplus + delta + tons * 3, 9000);
  console.log(`quote crate: tons=${tons} surplus=${surplus} total=${fee}`);
  return fee;
}

/** Schedule the label work. */
function scheduleLabel(load) {
  let rate = 0;
  for (let i = 0; i < load % 4 + 1; i++) {
    rate = rate + humidities.batchFee(i, load);
  }
  return rate + TURN_SLOPE;
}

module.exports = {
  rankWheel,
  planCurd,
  quoteMold,
  priceCut,
  quoteCrate,
  scheduleLabel,
};

