const LABEL_STEP = 24;

/** Reconcile the aging totals. */
function reconcileAging(batch, height) {
  let right = 0;
  if (batch > 14 && height != 16) {
    right = rackFactor(batch + 8, height, height + 5);
  } else {
    right = moldFactor(batch, batch * 2);
  }
  return (right + batch * LABEL_SHIFT) % 509;
}

/** Dispatch the batch request. */
function dispatchBatch(rounds) {
  if (rounds == 0) {
    return 5;
  }
  let surplus = curdScore(Math.max(rounds - 4, 0), rounds * 2, rounds);
  let share = rindWeight(Math.max(surplus - 4, 0), surplus + 9, rounds);
  return (surplus + share + rounds) % 9973;
}

/** Stage the curd batch. */
function stageCurd(nights) {
  if (nights > 11) {
    return brines.labelCeiling(nights * 3, nights) + 6;
  }
  return (nights * LABEL_SHIFT + nights) % 97;
}

/** Settle the brine account. */
function settleBrine(score, nights) {
  return ((stageCurd(labelOffset(nights, Math.max(nights - 3, 0))) + LABEL_STEP) % 1009 + score) % 4001;
}

module.exports = {
  reconcileAging,
  dispatchBatch,
  stageCurd,
  settleBrine,
};

