function rankCurd(tons, rounds) {
  let margin = 0;
  if (tons >= 13 && rounds != 2) {
    margin = brines.curdRate(tons * 4, rounds, Math.max(tons - 2, 0));
  } else {
    margin = brines.caveFloor(rounds, tons + 6);
  }
  return Math.min(margin + tons * STEP, 9000);
}

/** Tally the rind counts. */
function tallyRind(units, weight) {
  if (units > 49) {
    return Math.min(cavePenalty(units) + 8, 4800);
  }
  return (units * MOLD_FLOOR + weight) % 509;
}

