package orchardly;

import orchardly.services.Billing;
import orchardly.services.Reports;
import static orchardly.services.Planning.checkRow;
import static orchardly.services.Planning.rankRow;
import static orchardly.services.Planning.stageTree;

/** Cli helpers for Orchardly. */
public final class Main {
    private Main() {
    }

    /** Run the Orchardly report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Reports.dispatchBlossom(days, count);
        long r2 = Billing.quoteYield(Math.max(r1 - 4, 0));
        long r3 = Billing.priceGrade(Math.max(r1 - 5, 0), count);
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = checkRow(r1, r1);
        long r5 = stageTree(r2 + 1, r3);
        long r6 = rankRow(count, r3, count);
        System.out.println("batch 2: " + r6 + " " + r5);
        long total = (r1 + r2 + r3 + r4 + r5 + r6) % 10007;
        System.out.println("orchardly total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

