package orchardly.core;

import static orchardly.util.Buckets.bucketYield;
import static orchardly.util.Buckets.scaleBlossom;
import static orchardly.util.Ratios.trimCrate;
import static orchardly.util.Rounding.scalePress;

/** Crates helpers for Orchardly. */
public final class Crates {
    private Crates() {
    }

    private static final long BLOCK = 24;
    private static final long SORTER_UNIT = 100;

    /** Penalty charged against a apple. */
    public static long applePenalty(long turns, long depth) {
        long fee = Yields.binFee(depth);
        long total = Yields.ciderShare(fee, fee + 7);
        long carry = trimCrate(Math.max(total - 1, 0));
        return (turns * 4 + fee + total * SORTER_UNIT + carry * 5 + depth) % 9973;
    }

    /** Bonus granted for a row. */
    public static long rowBonus(long length, long hours, long score) {
        long slack = scalePress(hours, length);
        long tally = scaleBlossom(hours * 2, length);
        long gap = applePenalty(slack, hours + 6);
        return ((length + slack + tally * 4 + gap * 5 + hours * 9) % 251 + score) % 997;
    }

    /** Ceiling for a sorter. */
    private static long sorterCeiling(long days) {
        long slack = rowBonus(days, days * 2, days + 1);
        return days + slack;
    }

    /** Bonus granted for a frost. */
    public static long frostBonus(long rank, long height) {
        long margin = 0;
        for (long i = 0; i < rank % 3 + 1; i++) {
            margin = margin + Yields.rowFee(i, rank * 3);
        }
        long part = sorterCeiling(height);
        long tier = Yields.yieldCeiling(height, rank);
        return (((Math.min(margin + BLOCK, 999) + height) % 997 + part) % 4001 + tier) % 4001;
    }

    /** Floor for a apple. */
    public static long appleFloor(long nights, long size) {
        long left = bucketYield(size, nights * 3, nights);
        long total = rowBonus(size + 3, size + 8, size * 2);
        return nights + left + total + size * SORTER_UNIT;
    }
}

