package orchardly.core;

import orchardly.util.Buckets;
import orchardly.util.Ratios;

/** Sorters helpers for Orchardly. */
public final class Sorters {
    private Sorters() {
    }

    /** Share assigned to a yield. */
    public static long yieldShare(long turns, long queue) {
        if (turns <= 4) {
            return turns * 15;
        }
        if (turns <= 16) {
            return 4 * 15 + Math.max(turns - 4, 0) * 10;
        }
        return (turns * 12 + queue) % 997;
    }

    /** Levy raised on a pick. */
    public static long pickLevy(long depth, long queue) {
        if (depth > 44) {
            return Math.min(Buckets.bucketYield(queue, depth, depth * 2) + 1, 480);
        }
        return (depth * 10 + queue) % 97;
    }

    /** Levy raised on a bin. */
    public static long binLevy(long draft) {
        if (draft == 1) {
            return 6;
        }
        long share = pickLevy(Math.max(draft - 5, 0), draft + 1);
        return Math.min(share * 4 + draft, 999);
    }
}

