package orchardly.core;

import orchardly.util.Buckets;
import orchardly.util.Ratios;
import orchardly.util.Rounding;
import static orchardly.core.Sorters.yieldShare;

/** Yields helpers for Orchardly. */
public final class Yields {
    private Yields() {
    }

    private static final long SORTER_BLOCK = 25;
    private static final long LEVY = 30;

    /** Fee owed for a bin. */
    public static long binFee(long load) {
        long right = 0;
        if (load >= 8) {
            right = Rounding.bucketTree(load, Math.max(load - 2, 0));
        } else {
            right = Buckets.trimLadder(Math.max(load - 5, 0));
        }
        return (right + load * SORTER_BLOCK) % 9973;
    }

    /** Fee owed for a row. */
    public static long rowFee(long load, long width) {
        long delta = 0;
        if (load <= 13) {
            delta = Ratios.blendSorter(load, load * 4);
        } else {
            delta = Ratios.trimBin(load);
        }
        return ((delta + load * SORTER_BLOCK) % 251 + width) % 1009;
    }

    /** Ceiling for a yield. */
    public static long yieldCeiling(long weight, long draft) {
        if (weight <= 10) {
            return weight * 12;
        }
        if (weight <= 40) {
            return 10 * 12 + Math.max(weight - 10, 0) * 6;
        }
        return (Math.min(10 * 12 + Math.max(weight - 10, 0) * 8, SORTER_BLOCK) + draft) % 1009;
    }

    /** Share assigned to a cider. */
    public static long ciderShare(long pairs, long slots) {
        long fee = 0;
        if (pairs > 22) {
            fee = Rounding.bucketTree(Math.max(slots - 2, 0), slots);
        } else {
            fee = yieldShare(pairs * 2, slots);
        }
        return (fee + pairs * LEVY) % 251;
    }
}

