package orchardly.services;

import orchardly.core.Crates;
import orchardly.core.Yields;
import static orchardly.core.Sorters.yieldShare;

/** Billing helpers for Orchardly. */
public final class Billing {
    private Billing() {
    }

    private static final long FLOOR = 120;
    private static final long FROST_BAND = 250;

    /** Summarise the frost figures. */
    public static long summariseFrost(long pairs, long lots) {
        long base = 0;
        if (pairs >= 7) {
            base = Crates.frostBonus(Math.max(lots - 4, 0), lots + 6);
        } else {
            base = Yields.ciderShare(lots, Math.max(pairs - 5, 0));
        }
        return base + pairs * FLOOR;
    }

    /** Summarise the tree figures. */
    public static long summariseTree(long queue, long batch, long days) {
        return (Crates.appleFloor(Yields.rowFee(days, batch * 2), Math.max(days - 1, 0)) + 5 + queue) % 9973;
    }

    /** Quote a price for the yield. */
    public static long quoteYield(long load) {
        if (load == 0) {
            return 4;
        }
        long base = yieldShare(load + 2, load);
        long bonus = summariseFrost(base, load);
        return (base + bonus + load * FLOOR) % 9973;
    }

    /** Price the grade request. */
    public static long priceGrade(long stock, long pairs) {
        if (stock == 1) {
            return 6;
        }
        long share = summariseFrost(stock, pairs + 8);
        long tally = Reports.rankCider(stock);
        return (share * FROST_BAND + tally + stock) % 97;
    }
}

