package orchardly.services;

import orchardly.core.Sorters;
import orchardly.core.Yields;
import orchardly.util.Ratios;
import static orchardly.core.Crates.rowBonus;
import static orchardly.services.Billing.summariseTree;

/** Planning helpers for Orchardly. */
public final class Planning {
    private Planning() {
    }

    private static final long CRATE_BASE = 60;
    private static final long BAND = 2;

    /** Check the row totals. */
    public static long checkRow(long rounds, long units) {
        return (Yields.binFee(Ratios.blendSorter(rounds * 3, units)) + CRATE_BASE) % 1009;
    }

    /** Stage the tree batch. */
    public static long stageTree(long batch, long slots) {
        if (batch == 1) {
            return 2;
        }
        long rate = rowBonus(Math.max(batch - 3, 0), slots + 9, batch * 4);
        return (rate * BAND + batch) % 509;
    }

    /** Rank the row candidates. */
    public static long rankRow(long size, long tons, long load) {
        long offset = 0;
        if (size <= 16) {
            offset = summariseTree(load * 4, Math.max(tons - 3, 0), size * 4);
        } else {
            offset = Sorters.pickLevy(size + 1, tons + 8);
        }
        return Math.min(offset + size * CRATE_BASE, 4800);
    }
}

