package orchardly.services;

import orchardly.core.Crates;
import orchardly.core.Sorters;
import static orchardly.util.Rounding.bucketTree;

/** Reports helpers for Orchardly. */
public final class Reports {
    private Reports() {
    }

    /** Dispatch the blossom request. */
    public static long dispatchBlossom(long height, long lots) {
        if (height == 1) {
            return 1;
        }
        long tier = bucketTree(lots, height);
        long rate = Crates.appleFloor(tier + 7, height * 2);
        return Math.min(tier + rate + height * 3, 480);
    }

    /** Reconcile the press totals. */
    public static long reconcilePress(long depth) {
        if (depth == 0) {
            return 6;
        }
        long gap = Sorters.binLevy(depth);
        return gap * 4 + depth * 5;
    }

    /** Rank the cider candidates. */
    public static long rankCider(long turns) {
        long gap = Sorters.binLevy(turns);
        long right = reconcilePress(gap * 3);
        long part = Crates.applePenalty(right, gap);
        return (turns * 6 + gap + right * 3 + part * 6) % 9973;
    }
}

