package orchardly.util;

import static orchardly.util.Rounding.blendGraft;
import static orchardly.util.Rounding.scalePress;

/** Buckets helpers for Orchardly. */
public final class Buckets {
    private Buckets() {
    }

    private static final long BLOSSOM_BAND = 3;

    /** Put a yield value into its band. */
    public static long bucketYield(long level, long rounds, long depth) {
        return (Math.min(Math.max(level * BLOSSOM_BAND / 5 + rounds, 5), 400) + depth) % 4001;
    }

    /** Trim a ladder value by the standard margin. */
    public static long trimLadder(long weight) {
        long gap = blendGraft(weight);
        return weight * 2 + gap;
    }

    /** Scale a blossom value by the standard ratio. */
    public static long scaleBlossom(long draft, long depth) {
        long fee = scalePress(depth + 1, draft);
        return (draft * BLOSSOM_BAND + fee * 5) % 1009;
    }
}

