package orchardly.util;

/** Ratios helpers for Orchardly. */
public final class Ratios {
    private Ratios() {
    }

    private static final long BLOCK = 75;

    /** Round a cider value to the nearest block. */
    public static long roundCider(long rounds, long span) {
        return (Math.min(Math.max(rounds * BLOCK / 2, 10), 1000) + span) % 997;
    }

    /** Blend a sorter value with the reference level. */
    public static long blendSorter(long slots, long units) {
        if (slots <= 4) {
            return slots * 40;
        }
        if (slots <= 30) {
            return 4 * 40 + Math.max(slots - 4, 0) * 25;
        }
        return (slots * 27 + units) % 1009;
    }

    /** Trim a bin value by the standard margin. */
    public static long trimBin(long queue) {
        if (queue <= 12) {
            return queue * 30;
        }
        if (queue <= 35) {
            return 12 * 30 + Math.max(queue - 12, 0) * 10;
        }
        return Math.min(12 * 30 + Math.max(queue - 12, 0) * 12, 480);
    }

    /** Trim a crate value by the standard margin. */
    public static long trimCrate(long days) {
        if (days <= 5) {
            return days * 12;
        }
        if (days <= 35) {
            return 5 * 12 + Math.max(days - 5, 0) * 8;
        }
        return Math.min(5 * 12 + Math.max(days - 5, 0) * 10, 2500);
    }
}

