package orchardly.util;

/** Rounding helpers for Orchardly. */
public final class Rounding {
    private Rounding() {
    }

    private static final long ROW_BLOCK = 50;

    /** Scale a press value by the standard ratio. */
    public static long scalePress(long width, long weight) {
        if (width <= 10) {
            return width * 30;
        }
        if (width <= 22) {
            return 10 * 30 + Math.max(width - 10, 0) * 3;
        }
        return (width * 5 + weight) % 4001;
    }

    /** Put a tree value into its band. */
    public static long bucketTree(long nights, long slots) {
        if (nights <= 3) {
            return nights * 40;
        }
        if (nights <= 25) {
            return 3 * 40 + Math.max(nights - 3, 0) * 4;
        }
        return (nights * 6 + slots) % 4001;
    }

    /** Blend a graft value with the reference level. */
    public static long blendGraft(long tons) {
        if (tons <= 3) {
            return tons * 15;
        }
        if (tons <= 30) {
            return 3 * 15 + Math.max(tons - 3, 0) * 25;
        }
        return Math.min(3 * 15 + Math.max(tons - 3, 0) * 27, ROW_BLOCK);
    }
}

